def calculate_power_coefficients(i):
    # r^0 = 1 (1, 0, 0)
    # r^1 = r (0, 1, 0)
    # r^2 = r^2 (0, 0, 1)

    if i == 0:
        return (1, 0, 0)
    if i == 1:
        return (0, 1, 0)
    if i == 2:
        return (0, 0, 1)

    # We use dynamic programming (memoization)
    memo = {0: (1, 0, 0), 1: (0, 1, 0), 2: (0, 0, 1)}

    for j in range(2, i):
        A_j, B_j, C_j = memo[j]

        # r^{j+1} = 10C_j + (A_j - C_j)r + (B_j - C_j)r^2
        A_next = 10 * C_j
        B_next = A_j - C_j
        C_next = B_j - C_j
        memo[j+1] = (A_next, B_next, C_next)

    return memo[i]

# Test i=3
